import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CRFziyHp.js";const p=JSON.parse('{"title":"TabBar 配置","description":"TabBar 配置：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/tabbar.md","filePath":"features/ui-editor/tabbar.md","lastUpdated":1785018026000}'),o={name:"features/ui-editor/tabbar.md"};function l(n,t,s,i,b,h){return r(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="tabbar-配置" tabindex="-1">TabBar 配置 <a class="header-anchor" href="#tabbar-配置" aria-label="Permalink to &quot;TabBar 配置&quot;">​</a></h1><p>路径：<strong>UI管理 → TabBar配置</strong></p><p>底部 Tab 导航 <strong>独立于页面画布</strong> 存储。改 TabBar 不会自动改首页 UI，两者需分别保存。</p><h2 id="页面说明" tabindex="-1">页面说明 <a class="header-anchor" href="#页面说明" aria-label="Permalink to &quot;页面说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>功能</th></tr></thead><tbody><tr><td><strong>左侧（宽屏）</strong></td><td>区域选择 + TabBar 效果预览</td></tr><tr><td><strong>右侧</strong></td><td>Tab 项列表与样式配置</td></tr><tr><td><strong>顶栏</strong></td><td><strong>保存配置</strong> 按钮</td></tr></tbody></table><p>手机端底部切换 <strong>预览 / 配置编辑</strong>。</p><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><h3 id="_1-选择区域" tabindex="-1">1. 选择区域 <a class="header-anchor" href="#_1-选择区域" aria-label="Permalink to &quot;1. 选择区域&quot;">​</a></h3><p>顶部 <strong>配置区域</strong>：</p><ul><li><strong>平台默认（0）</strong>：未单独配置的区域继承此 TabBar</li><li><strong>具体区域</strong>：覆盖平台默认，仅该区域用户生效</li></ul><h3 id="_2-总开关" tabindex="-1">2. 总开关 <a class="header-anchor" href="#_2-总开关" aria-label="Permalink to &quot;2. 总开关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>显示 TabBar</strong></td><td>关闭后客户端隐藏整个底部导航（慎用）</td></tr></tbody></table><h3 id="_3-编辑-tab-项" tabindex="-1">3. 编辑 Tab 项 <a class="header-anchor" href="#_3-编辑-tab-项" aria-label="Permalink to &quot;3. 编辑 Tab 项&quot;">​</a></h3><p>每个 Tab 可配置：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>文字</td><td>底部显示文案</td></tr><tr><td>图标</td><td>未选中 / 选中两套图标（图标字体或图片）</td></tr><tr><td>点击动作</td><td>一般为 <strong>切换 Tab</strong> 到某个页面路径</td></tr><tr><td>角标</td><td>可选数字角标（部分场景）</td></tr></tbody></table><p>常见 Tab 对应关系：</p><table tabindex="0"><thead><tr><th>Tab 名称</th><th>通常跳转</th><th>对应 UI 页面类型</th></tr></thead><tbody><tr><td>首页</td><td>首页路由</td><td><strong>应用首页（home）</strong></td></tr><tr><td>发现/圈子</td><td>发现页路由</td><td><strong>功能页面（feature）</strong></td></tr><tr><td>消息</td><td>消息 Tab</td><td><strong>消息中心（news）</strong> 面板</td></tr><tr><td>我的</td><td>个人中心 Tab</td><td><strong>个人中心（profile）</strong> 面板</td></tr></tbody></table><h3 id="_4-中间「发布」按钮-可选" tabindex="-1">4. 中间「发布」按钮（可选） <a class="header-anchor" href="#_4-中间「发布」按钮-可选" aria-label="Permalink to &quot;4. 中间「发布」按钮（可选）&quot;">​</a></h3><p>部分站点 TabBar 中间为 <strong>凸起发布按钮</strong>，点击打开发布弹窗而非切换页面。</p><p>可配置：</p><ul><li>是否启用中间按钮</li><li>发布弹窗 <strong>主题样式</strong>（颜色、圆角）</li><li>弹窗内 <strong>菜单项</strong>（发笔记、发闲置、跑腿等）</li></ul><p>在 TabBar 配置面板内编辑，保存后客户端点击中间按钮生效。</p><h3 id="_5-tabbar-外观" tabindex="-1">5. TabBar 外观 <a class="header-anchor" href="#_5-tabbar-外观" aria-label="Permalink to &quot;5. TabBar 外观&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>背景色</td><td>Tab 栏底色</td></tr><tr><td>边框色</td><td>顶部分割线</td></tr><tr><td>胶囊模式</td><td>底部 Tab 呈悬浮胶囊形态</td></tr><tr><td>液态玻璃</td><td>毛玻璃模糊效果（可调校 blur、饱和度、高光）</td></tr><tr><td>圆角</td><td>顶部左右圆角</td></tr><tr><td>点击震动</td><td>切换 Tab 时震动反馈</td></tr></tbody></table><p>右侧预览区可实时查看效果。</p><h3 id="_6-保存" tabindex="-1">6. 保存 <a class="header-anchor" href="#_6-保存" aria-label="Permalink to &quot;6. 保存&quot;">​</a></h3><p>点击 <strong>保存配置</strong>。未保存离开页面会丢失修改。</p><h2 id="与页面配置的配合" tabindex="-1">与页面配置的配合 <a class="header-anchor" href="#与页面配置的配合" aria-label="Permalink to &quot;与页面配置的配合&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TabBar 决定「点哪个 Tab」</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>页面配置决定「进入 Tab 后看到什么」</span></span></code></pre></div><p><strong>检查清单：</strong></p><ul><li>[ ] Tab 点击动作指向的路由存在且可访问</li><li>[ ] 对应 <strong>页面类型</strong> 已在 <strong>页面配置</strong> 中 <strong>启用</strong></li><li>[ ] 新业务 Tab（外卖、闲置）仅在模块开通后添加，避免用户点进空白页</li></ul><h2 id="多区域-tabbar" tabindex="-1">多区域 TabBar <a class="header-anchor" href="#多区域-tabbar" aria-label="Permalink to &quot;多区域 TabBar&quot;">​</a></h2><ol><li>先做 <strong>平台默认</strong> TabBar</li><li>某区域需减少 Tab（如未开外卖）→ 切换到该区域 → 删除或隐藏对应 Tab → 保存</li><li>客户端切换区域后 Tab 数量可能变化</li></ol><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ol><li>修改某 Tab 文案（如「首页」→「广场」）并保存</li><li>客户端切换至 <strong>同一区域</strong></li><li>杀进程重进，底部文案已更新</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Tab 点击无反应或空白页</strong></p><ul><li>点击动作路径错误</li><li>目标页面 UI 未 <strong>启用</strong></li><li>业务模块未开通</li></ul><p><strong>改了 TabBar 首页内容没变</strong></p><ul><li>首页内容由 <strong>应用首页（home）</strong> 页面配置控制，不是 TabBar</li></ul><p><strong>预览与客户端不一致</strong></p><ul><li>确认区域一致；部分样式仅小程序/App 完整呈现</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ui-editor/page-types">页面类型说明</a></li><li><a href="/features/ui-editor/getting-started">快速上手</a></li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li></ul>`,44)])])}const u=a(o,[["render",l]]);export{p as __pageData,u as default};
